  {"id": "strike", "type": "~~struck~~", "becomes": "Struck through.", "covers": ["inline:strike"]},
  {"id": "spoiler", "type": "||hidden||", "becomes": "Hidden until each reader selects it.", "covers": ["inline:spoiler"]},
  {"id": "code", "type": "`code`", "becomes": "Code, in a fixed-width font. Nothing inside is formatted or turned into anything.", "covers": ["inline:code"]},
