  {"id": "link", "type": "[the guide](https://example.com)", "becomes": "A link with your words. Only web, mailto and tel addresses become links; ![image](address) shows as a link too.", "covers": ["inline:link", "inline:nolink", "inline:image"]},
  {"id": "quote", "type": "> quoted", "becomes": "A quote. Quotes may hold other quotes, three deep.", "covers": ["block:quote"]},
  {"id": "list", "type": "- item  * item  1. item", "becomes": "A bulleted or numbered list. Indent by two spaces to nest, three levels deep.", "covers": ["block:list"]},
